def algorithm(func, dim, lb, ub, budget, rng):
    x = np.zeros(dim)
    best_x = x.copy()
    for _ in range(budget):
        x += 2 * (rng.uniform(-1, 1, size=dim) - 0.5)
        x = np.clip(x, lb, ub)
        f_x = func(x)
        if f_x < func(best_x):
            best_x = x
    return best_x
